type AdwaitaConfig = {
    size: number;
    color: string;
    strokeWidth: number;
    /**
     * @deprecated Use `nonScalingStroke` instead.
     */
    absoluteStrokeWidth: boolean;
    nonScalingStroke: boolean;
    className: string;
};
type AdwaitaProviderProps = {
    children: ReactNode;
} & Partial<AdwaitaConfig>;
declare function AdwaitaProvider({ children, size, color, strokeWidth, absoluteStrokeWidth, nonScalingStroke, className, }: AdwaitaProviderProps): react.FunctionComponentElement<react.ProviderProps<AdwaitaProps>>;
declare const useAdwaitaContext: () => AdwaitaProps;

/**
 * Creates a Adwaita icon component from icon data.
 *
 * @param icon Icon data object.
 * @returns Adwaita icon component.
 */
declare function createAdwaitaIcon(icon: AdwaitaIconData): AdwaitaIcon;
/**
 * Creates a Adwaita icon component from the legacy icon arguments.
 *
 * @param iconName Icon name.
 * @param iconNode Icon node.
 * @param aliases Optional icon aliases.
 * @returns Adwaita icon component.
 */
declare function createAdwaitaIcon(iconName: string, iconNode: AdwaitaIconNode[], aliases?: string[]): AdwaitaIcon;

/**
 * Adwaita icon component
 *
 * @component Icon
 * @param {object} props
 * @param {string} props.color - The color of the icon
 * @param {number} props.size - The size of the icon
 * @param {number} props.strokeWidth - The stroke width of the icon
 * @param {boolean} props.absoluteStrokeWidth - Whether to use absolute stroke width
 * @param {boolean} props.nonScalingStroke - Whether to use non scaling strokes
 * @param {string} props.className - The class name of the icon
 * @param {AdwaitaIconNode[]} props.children - The children of the icon
 * @param {AdwaitaIconNode[]} props.iconNode - The icon node of the icon
 *
 * @returns {ForwardRefExoticComponent} AdwaitaIcon
 */
declare const Icon: react.ForwardRefExoticComponent<(Omit<AdwaitaProps & {
    iconNode: AdwaitaIconNode[];
    icon?: never;
}, "ref"> | Omit<AdwaitaProps & {
    icon: AdwaitaIconData;
    iconNode?: never;
}, "ref">) & react.RefAttributes<SVGSVGElement>>;

